/* Cloud Pet customer H5. Shared state is authoritative; no private demo data. */
export const customerRoutes = [
  {page:'home',title:'C01 顾客首页'}, {page:'services',title:'C02 服务项目'},
  {page:'service',id:'s1',title:'C03 服务详情'}, {page:'select-pet',title:'C04 选择宠物'},
  {page:'booking',title:'C05 选择时段'}, {page:'confirm',title:'C06 预约确认'},
  {page:'success',id:'a1',title:'C07 预约成功'}, {page:'appointments',title:'C08 我的预约'},
  {page:'appointment',id:'a1',title:'C09 预约详情'}, {page:'pets',title:'C10 我的宠物'},
  {page:'pet',id:'p1',title:'C11 宠物档案'}, {page:'pet-edit',id:'p1',title:'C12 编辑宠物'},
  {page:'reports',title:'C13 护理手记'}, {page:'report',id:'r1',title:'C14 护理详情'},
  {page:'gift',id:'g1',title:'C15 专属礼物'}, {page:'contact',title:'C16 联系门店'},
  {page:'profile',title:'C17 个人中心'}, {page:'messages',title:'C18 消息与订阅'}
];

const seasonNames={spring:'春',summer:'夏',autumn:'秋',winter:'冬'};
const periodNames={morning:'清晨',day:'白天',sunset:'夕阳',night:'夜晚'};
const greetings={morning:'早安',day:'午安',sunset:'傍晚好',night:'晚安'};
const editableStatuses=['pending','confirmed'];
const activeStatuses=['pending','confirmed','arrived','serving'];
const find=(arr,id)=>(arr||[]).find(x=>x.id===id);
const ownPets=ctx=>(ctx.state.pets||[]).filter(x=>x.customerId==='c1');
const ownAppointments=ctx=>(ctx.state.appointments||[]).filter(x=>x.customerId==='c1');
const ownReports=ctx=>(ctx.state.reports||[]).filter(x=>x.customerId==='c1');
const ownGifts=ctx=>(ctx.state.gifts||[]).filter(x=>x.customerId==='c1'&&['confirmed','ready','delivered'].includes(x.status));
const minutes=t=>{const [h,m]=String(t||'0:0').split(':').map(Number);return h*60+m};
const addDays=(date,n)=>{const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const e=(ctx,s)=>ctx.ui.esc(s??'');
const icon=(ctx,name,size=22)=>ctx.ui.icon(name,size);
const money=(ctx,n)=>ctx.ui.money(Number(n)||0);
const go=(ctx,label,page,id='',cls='button secondary')=>`<button type="button" class="${cls}" data-go="${page}"${id?` data-id="${e(ctx,id)}"`:''}>${label}</button>`;
const act=(ctx,label,action,attrs='',cls='button primary')=>`<button type="button" class="${cls}" data-action="c.${action}" ${attrs}>${label}</button>`;
const header=(ctx,title,back='home',subtitle='')=>`<header class="page-head"><div class="row">${go(ctx,icon(ctx,'chevron'),back,'','button ghost back-button')}<div><p class="eyebrow">陪伴更美好的日常</p><h1>${e(ctx,title)}</h1></div></div>${subtitle?`<p class="muted">${subtitle}</p>`:''}</header>`;
const page=(ctx,title,body,back='home',subtitle='')=>`<div class="page customer-page">${header(ctx,title,back,subtitle)}${body}</div>`;
const field=(ctx,label,name,value='',type='text',attrs='')=>`<label class="field"><span>${label}</span><input class="input" type="${type}" name="${name}" value="${e(ctx,value)}" ${attrs}></label>`;
const textarea=(ctx,label,name,value='',attrs='')=>`<label class="field"><span>${label}</span><textarea class="input" name="${name}" rows="3" ${attrs}>${e(ctx,value)}</textarea></label>`;
const errorBox=()=>'<div class="notice error form-error" role="alert" hidden></div>';
const section=(ctx,title,link='')=>`<div class="section-title between"><h2>${title}</h2>${link}</div>`;
const photo=(ctx,pet,size=56)=>ctx.ui.petAvatar(pet||{name:'宠物'},size);
const datum=(ctx,label,value)=>`<div class="between detail-row"><span class="muted">${label}</span><span>${e(ctx,value||'未填写')}</span></div>`;
const tag=(ctx,text,tone='')=>ctx.ui.tag(text,tone);
const noData=(ctx,title,body,button='')=>ctx.ui.empty(title,body,button);
function employeeNames(ctx,service){return (ctx.state.employees||[]).filter(x=>(service.employeeIds||[]).includes(x.id)&&x.active!==false).map(x=>x.name).join('、')||'门店安排'}
function supportsPet(service,pet){const cat=pet?.species==='cat'||(!pet?.species&&/猫|布偶|暹罗|英短|美短/.test(pet?.breed||''));return cat?/猫|cat/i.test(service?.species||''):/犬|狗|dog/i.test(service?.species||'');}
function ensurePetService(ctx,d,pet){const p=pet||find(ownPets(ctx),d.petId),s=find(ctx.state.services,d.serviceId);if(p&&(!s||!supportsPet(s,p))){d.serviceId=(ctx.state.services||[]).find(x=>x.enabled!==false&&supportsPet(x,p))?.id||'';d.employeeId='';d.time='';}return d;}
function serviceOf(ctx,appt){return find(ctx.state.services,appt?.serviceId)||{name:'护理服务',price:0,duration:60}}
function petOf(ctx,id){return find(ownPets(ctx),id)||{name:'小可爱',breed:'宠物'}}
function reportCard(ctx,r){const p=petOf(ctx,r.petId), a=find(ctx.state.appointments,r.appointmentId), staff=find(ctx.state.employees,r.employeeId);return `<button class="glass care-record" data-go="report" data-id="${e(ctx,r.id)}">${photo(ctx,p,80)}<span class="care-record-copy"><strong>${e(ctx,p.name)}，蓬松回家的一天</strong><span class="muted small">${e(ctx,r.date)} · ${e(ctx,serviceOf(ctx,a).name)}</span><span class="muted small">护理师 ${e(ctx,staff?.name||'小夏')}</span></span>${tag(ctx,'已完成','success')}</button>`}
function appointmentCard(ctx,a){const p=petOf(ctx,a.petId),s=serviceOf(ctx,a),staff=find(ctx.state.employees,a.employeeId);return `<button class="glass card appointment-card" data-go="appointment" data-id="${e(ctx,a.id)}"><span class="row">${photo(ctx,p,54)}<span class="grow"><strong>${e(ctx,p.name)} · ${e(ctx,s.name)}</strong><span class="small muted">${e(ctx,a.date)} ${e(ctx,a.time)} · ${s.duration} 分钟</span></span>${ctx.ui.status(a.status)}</span><span class="between small card-bottom"><span class="muted">${e(ctx,staff?.name||'门店安排')} · ${e(ctx,ctx.state.store.name)}</span><span>${money(ctx,a.amount??s.price)} ${icon(ctx,'arrow',16)}</span></span></button>`}

function home(ctx){
 const p=ownPets(ctx).find(x=>!x.deceased), report=ownReports(ctx).slice().sort((a,b)=>b.date.localeCompare(a.date))[0];
 const {season='spring',period='morning'}=ctx.theme||{};
 const headlines={spring:period==='night'?'晚风里，安心相伴。':'一起，去撒欢。',summer:period==='night'?'把清凉，留给晚风。':'一起，去追风。',autumn:period==='night'?'把秋夜，轻轻收藏。':'把秋天，慢慢收藏。',winter:period==='night'?'把温暖，留给今晚。':'今天，也很温暖。'};
 const upcoming=ownAppointments(ctx).find(x=>activeStatuses.includes(x.status));
 const reportPet=report?petOf(ctx,report.petId):null, reportAppt=report?find(ctx.state.appointments,report.appointmentId):null, reportStaff=report?find(ctx.state.employees,report.employeeId):null;
 return `<div class="customer-home locked-home">
 <section class="home-hero">
  <div class="scene home-scene" aria-hidden="true"></div>
  <div class="home-brand row"><span class="home-logo"><img src="./assets/logo.svg" alt=""></span><span class="home-brand-text"><strong>${e(ctx,ctx.state.store.name)}</strong></span><button type="button" class="home-capsule" data-action="c.home-menu" aria-label="打开个人中心菜单"><b>•••</b><i></i><span></span></button></div>
  <div class="home-welcome"><span class="glass season-label">${icon(ctx,period==='night'?'moon':'sun',15)} ${seasonNames[season]} · ${periodNames[period]}</span><p>${greetings[period]||'你好'}，${e(ctx,p?.name||'小可爱')}</p><h1>${headlines[season]||headlines.spring}</h1></div>
 </section>
 <div class="home-content">
  <article class="glass home-booking"><div class="between home-booking-title"><h2>给${e(ctx,p?.name||'小可爱')}，约个好时光</h2><span class="home-availability"><i aria-hidden="true"></i>${period==='night'?'明日可约':'今日可约'}</span></div><div class="between home-booking-bottom"><p>洗护 · 美容 · 日常护理</p>${act(ctx,`${icon(ctx,'calendar',20)} 预约护理`,'start-booking')}</div></article>
  <div class="home-entries">${[['bath','服务项目','services'],['book','护理手记','reports'],['store','联系门店','contact']].map(([i,t,r])=>`<button data-go="${r}" class="home-entry"><span class="cute-entry-icon">${icon(ctx,i,64)}</span><strong>${t}</strong></button>`).join('')}</div>
  ${section(ctx,'最近的照顾',go(ctx,`全部 ${icon(ctx,'chevron',17)}`,'reports','','text-link'))}
  ${report?`<button class="glass care-record home-care-record" data-go="report" data-id="${e(ctx,report.id)}">${photo(ctx,reportPet,80)}<span class="care-record-copy"><strong>蓬松回家的一天</strong><span class="muted small">${e(ctx,ctx.ui.date(report.date))} · ${e(ctx,serviceOf(ctx,reportAppt).name)}</span><span class="muted small">${icon(ctx,'user',14)} 护理师 ${e(ctx,reportStaff?.name||'小夏')}</span></span>${tag(ctx,'已完成','success')}</button>`:noData(ctx,'每一份照顾，都值得记录','第一次护理完成后，温暖的手记就会出现在这里。',go(ctx,'看看服务','services'))}
  ${upcoming?`<button class="glass upcoming-card between" data-go="appointment" data-id="${e(ctx,upcoming.id)}"><span class="row">${icon(ctx,'calendar',21)}<span><strong>下次见面 · ${e(ctx,ctx.ui.date(upcoming.date))} ${e(ctx,upcoming.time)}</strong><small class="muted">${e(ctx,petOf(ctx,upcoming.petId).name)} · ${e(ctx,serviceOf(ctx,upcoming).name)}</small></span></span>${ctx.ui.status(upcoming.status)}</button>`:''}
 </div></div>`;
}

function services(ctx){
 const list=ctx.state.services||[], category=ctx.draft.serviceCategory||'全部',cats=['全部',...new Set(list.map(x=>x.category||'日常护理'))];
 return page(ctx,'服务项目',`<div class="tabs scroll-chips">${cats.map(c=>act(ctx,e(ctx,c),'service-category',`data-value="${e(ctx,c)}"`,`chip ${c===category?'selected':''}`)).join('')}</div><div class="stack">${list.filter(x=>category==='全部'||(x.category||'日常护理')===category).map(s=>`<button class="glass card service-card" data-go="service" data-id="${e(ctx,s.id)}"><span class="service-symbol">${icon(ctx,s.category==='美容'?'paw':'bath',48)}</span><span class="grow"><strong>${e(ctx,s.name)}</strong><span class="muted small">${e(ctx,s.description)}</span><span class="service-meta small">${s.duration} 分钟 · ${e(ctx,s.species||'猫咪与狗狗')}</span><span class="between"><span class="amount">${money(ctx,s.price)}</span>${s.enabled===false?tag(ctx,'暂不开放'):tag(ctx,'可预约','success')}</span></span></button>`).join('')||noData(ctx,'服务正在准备中','门店整理好服务后，即可在这里预约。',go(ctx,'联系门店','contact'))}</div>`,'home','把专业的事交给我们，把轻松的时光留给你。');
}
function service(ctx){const s=find(ctx.state.services,ctx.id);if(!s)return missing(ctx,'服务项目','services');return page(ctx,s.name,`<div class="glass service-feature"><span class="service-illustration">${icon(ctx,'bath',105)}</span><p class="eyebrow">认真对待每一个小可爱</p><h2>${e(ctx,s.name)}</h2><p>${e(ctx,s.description)}</p><strong class="amount">${money(ctx,s.price)}<small> / 次</small></strong></div><section class="glass card stack">${datum(ctx,'预计时长',`${s.duration} 分钟`)}${datum(ctx,'适用宠物',s.species)}${datum(ctx,'护理师',employeeNames(ctx,s))}${datum(ctx,'开放状态',s.enabled===false?'暂不开放预约':'开放预约')}</section><div class="notice">${icon(ctx,'heart',19)} 请提前告知过敏、皮肤或情绪注意事项。具体服务内容与价格会在到店时与你确认；本演示不收取费用。</div>${s.enabled===false?go(ctx,'咨询门店','contact'):act(ctx,'为它预约这项服务','start-booking',`data-service="${e(ctx,s.id)}"`,'button primary full')}`,'services');}

function draftBooking(ctx){if(!ctx.draft.booking){const p=ownPets(ctx).find(x=>!x.deceased),s=(ctx.state.services||[]).find(x=>x.enabled!==false);ctx.draft.booking={petId:p?.id||'',serviceId:s?.id||'',date:ctx.state.today,employeeId:'',time:'',notes:''};}return ctx.draft.booking;}
function selectPet(ctx){const d=draftBooking(ctx), pets=ownPets(ctx).filter(x=>!x.deceased);return page(ctx,'这次，陪谁来？',`<div class="stepper"><span class="selected">1 选择宠物</span><span>2 选择时段</span><span>3 确认预约</span></div><div class="stack">${pets.map(p=>act(ctx,`${photo(ctx,p,64)}<span class="grow"><strong>${e(ctx,p.name)}</strong><small class="muted">${e(ctx,p.breed)} · ${e(ctx,p.weight||'—')} kg</small></span>${icon(ctx,'arrow',20)}`,'choose-pet',`data-id="${e(ctx,p.id)}"`,`glass card row pet-choice ${d.petId===p.id?'selected':''}`)).join('')||noData(ctx,'先认识一下你的小可爱','建立宠物档案后，我们就能提供更贴心的照顾。')}${act(ctx,`${icon(ctx,'plus',20)} 添加宠物档案`,'new-pet','data-return="booking"','button secondary full')}</div>`,'services');}
function availableEmployees(ctx,d){const s=find(ctx.state.services,d.serviceId);return (ctx.state.employees||[]).filter(x=>x.active!==false&&(!s?.employeeIds?.length||s.employeeIds.includes(x.id)));}
function openingHours(ctx){return ctx.state.openingHours||{open:'09:00',close:'18:00',start:540,end:1080};}
function slotEmployee(ctx,d,time){const s=find(ctx.state.services,d.serviceId);if(!s)return null;const t=minutes(time),duration=Number(s.duration)||60,hours=openingHours(ctx);if(t<hours.start||t+duration>hours.end)return null;const original=d.editId?find(ownAppointments(ctx),d.editId):null;return availableEmployees(ctx,d).filter(x=>!d.employeeId||d.employeeId===x.id).find(emp=>!(ctx.state.availability||[]).some(b=>{if(b.date!==d.date||b.employeeId!==emp.id)return false;if(original&&b.date===original.date&&b.time===original.time&&b.employeeId===original.employeeId)return false;const from=minutes(b.time),to=from+Number(b.duration||60);return t<to&&t+duration>from;}));}
function slots(ctx,d){const out=[],hours=openingHours(ctx);for(let m=hours.start;m<hours.end;m+=30){const t=`${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`,emp=slotEmployee(ctx,d,t),selected=d.time===t;out.push(`<button type="button" data-action="c.slot" data-time="${t}" class="slot ${selected?'selected':''}" ${emp?'':'disabled'} aria-pressed="${selected}">${t}<small>${emp?selected?'已选择':'可预约':'不可约'}</small></button>`);}return out.join('');}
function booking(ctx){const d=draftBooking(ctx),s=find(ctx.state.services,d.serviceId),p=find(ownPets(ctx),d.petId),employees=availableEmployees(ctx,d);if(!p)return selectPet(ctx);return page(ctx,d.editId?'换个合适的时间':'约一个好时光',`<div class="stepper"><span>1 选择宠物</span><span class="selected">2 选择时段</span><span>3 确认预约</span></div><form data-action="c.booking-review" class="stack" id="customer-booking-form">${errorBox()}<div class="glass card row">${photo(ctx,p,54)}<div class="grow"><strong>${e(ctx,p.name)}</strong><small class="muted">${e(ctx,p.breed)} · ${e(ctx,p.weight||'—')} kg</small></div>${d.editId?'':go(ctx,'更换','select-pet','','button ghost')}</div><input type="hidden" name="petId" value="${e(ctx,d.petId)}"><div class="glass card stack"><label class="field"><span>服务项目</span><select class="input" name="serviceId" ${d.editId?'disabled':''}>${(ctx.state.services||[]).filter(x=>(x.enabled!==false&&supportsPet(x,p))||x.id===d.serviceId).map(x=>`<option value="${e(ctx,x.id)}" ${d.serviceId===x.id?'selected':''}>${e(ctx,x.name)} · ${money(ctx,x.price)} · ${x.duration} 分钟</option>`).join('')}</select>${d.editId?`<input type="hidden" name="serviceId" value="${e(ctx,d.serviceId)}">`:''}</label>${datum(ctx,'到访门店',ctx.state.store.name)}${field(ctx,'预约日期','date',d.date,'date',`required min="${ctx.state.today}" max="${addDays(ctx.state.today,29)}"`)}<label class="field"><span>护理师 <small class="muted">可选</small></span><select class="input" name="employeeId"><option value="">由门店为我安排</option>${employees.map(x=>`<option value="${e(ctx,x.id)}" ${d.employeeId===x.id?'selected':''}>${e(ctx,x.name)}</option>`).join('')}</select></label></div><section><div class="section-title between"><h2>选择开始时间</h2><small class="muted">预计 ${s?.duration||60} 分钟</small></div><p class="small muted">已按护理时长和护理师排期筛选。灰色时段已占用或无法在营业时间内完成。</p><input type="hidden" name="time" value="${e(ctx,d.time)}"><div class="booking-slots">${slots(ctx,d)}</div><p class="small muted">营业时间 ${e(ctx,openingHours(ctx).open)}–${e(ctx,openingHours(ctx).close)} · 可预约未来 30 天</p></section>${textarea(ctx,'给护理师的话（选填）','notes',d.notes,'maxlength="500" placeholder="例如：耳朵比较敏感，吹风时请温柔一点。"')}${p.allergies?`<div class="notice">${icon(ctx,'heart',18)} 已带入注意事项：${e(ctx,p.allergies)}</div>`:''}<button class="button primary full" type="submit">下一步，确认预约 ${icon(ctx,'arrow',19)}</button></form>`,'select-pet');}

function summary(ctx,d){const p=petOf(ctx,d.petId),s=serviceOf(ctx,d),emp=find(ctx.state.employees,d.employeeId);return `<div class="row">${photo(ctx,p,62)}<div><h2>${e(ctx,p.name)}</h2><p class="muted">${e(ctx,s.name)}</p></div></div><div class="detail-list">${datum(ctx,'到访时间',`${d.date} ${d.time}`)}${datum(ctx,'预计时长',`${s.duration} 分钟`)}${datum(ctx,'护理师',emp?.name||'门店安排')}${datum(ctx,'门店',ctx.state.store.name)}${datum(ctx,'服务参考价',money(ctx,d.amount??s.price))}</div>${d.notes?`<div class="notice">${e(ctx,d.notes)}</div>`:''}`;}
function confirm(ctx){const d=draftBooking(ctx);if(!d.time)return page(ctx,'确认预约',noData(ctx,'还差一个见面的时间','先为小可爱选好时间，再确认这次预约。',go(ctx,'选择预约时段','booking')),'booking');return page(ctx,'确认这次见面',`<div class="stepper"><span>1 选择宠物</span><span>2 选择时段</span><span class="selected">3 确认预约</span></div><form data-action="c.booking-submit" class="stack">${errorBox()}<div class="glass card stack">${summary(ctx,d)}</div><div class="notice">提交后门店会收到预约。此为 H5 演示，不会产生实际订单或支付。最终价格以到店确认的服务内容为准。</div><label class="check-row"><input name="agree" type="checkbox" required>我已确认宠物、服务与时间信息</label><button class="button primary full" type="submit">${d.editId?'确认修改预约':'提交预约'} ${icon(ctx,'check',20)}</button>${go(ctx,'再调整一下','booking','','button ghost full')}</form>`,'booking');}
function success(ctx){const a=find(ownAppointments(ctx),ctx.id||ctx.draft.lastBookingId);if(!a)return page(ctx,'预约已记录',noData(ctx,'到我的预约查看记录','你的预约会在门店与员工工作台同步。',go(ctx,'我的预约','appointments')));return page(ctx,'期待和你见面',`<div class="success-banner"><span class="success-circle">${icon(ctx,'check',38)}</span><h2>${a.status==='pending'?'预约提交成功':'预约已保存'}</h2><p class="muted">${e(ctx,petOf(ctx,a.petId).name)}的好时光，我们记下啦。</p></div><div class="glass card stack">${summary(ctx,a)}</div><p class="notice">${icon(ctx,'calendar',20)} 请提前 10 分钟到店。如需调整，在预约详情中即可修改或取消。</p>${go(ctx,'查看预约详情','appointment',a.id,'button primary full')}${go(ctx,'回到首页','home','','button ghost full')}`,'appointments');}
function appointments(ctx){const filter=ctx.draft.appointmentFilter||'进行中',all=ownAppointments(ctx).slice().sort((a,b)=>`${b.date}${b.time}`.localeCompare(`${a.date}${a.time}`));const list=all.filter(x=>filter==='全部'||(filter==='进行中'?activeStatuses.includes(x.status):['completed','cancelled'].includes(x.status)));return page(ctx,'我的预约',`<div class="tabs">${['进行中','已结束','全部'].map(x=>act(ctx,x,'appointment-filter',`data-value="${x}"`,`chip ${filter===x?'selected':''}`)).join('')}</div><div class="stack">${list.map(a=>appointmentCard(ctx,a)).join('')||noData(ctx,filter==='进行中'?'还没有约好的见面':'这里还没有预约记录','挑一个轻松的时间，把小可爱交给我们。',act(ctx,'预约一次护理','start-booking'))}</div>`,'home');}
function appointment(ctx){const a=find(ownAppointments(ctx),ctx.id);if(!a)return missing(ctx,'预约','appointments');const r=ownReports(ctx).find(x=>x.appointmentId===a.id),o=(ctx.state.orders||[]).find(x=>x.appointmentId===a.id);return page(ctx,'预约详情',`<div class="between appointment-status"><span class="eyebrow">预约 ${e(ctx,a.id)}</span>${ctx.ui.status(a.status)}</div><div class="glass card stack">${summary(ctx,a)}</div><div class="timeline">${[['pending','已提交预约'],['confirmed','门店确认'],['arrived','到店接待'],['serving','温柔护理中'],['completed','完成护理']].map(([k,t],i)=>`<div class="timeline-item ${['pending','confirmed','arrived','serving','completed'].indexOf(a.status)>=i?'done':''}"><span class="timeline-dot"></span><span>${t}</span></div>`).join('')}</div>${a.status==='cancelled'?`<div class="notice">预约已取消${a.cancelReason?`：${e(ctx,a.cancelReason)}`:''}。期待下次见面。</div>`:''}${o?`<div class="glass card between"><span>本次消费记录 ${tag(ctx,o.status==='confirmed'?'门店已确认':'待门店确认')}</span><strong>${money(ctx,o.amount)}</strong></div>`:''}${r?go(ctx,`${icon(ctx,'book',22)} 查看这次护理手记`,'report',r.id,'button primary full'):''}${editableStatuses.includes(a.status)?`<div class="grid2">${act(ctx,'修改预约','edit-booking',`data-id="${e(ctx,a.id)}"`,'button secondary')}${act(ctx,'取消预约','cancel-booking',`data-id="${e(ctx,a.id)}"`,'button ghost')}</div>`:''}${go(ctx,'联系门店','contact','','button secondary full')}${['completed','cancelled'].includes(a.status)?act(ctx,'再约一次护理','start-booking',`data-service="${e(ctx,a.serviceId)}" data-pet="${e(ctx,a.petId)}"`,'button primary full'):''}`,'appointments');}

function pets(ctx){const pets=ownPets(ctx);return page(ctx,'我的宠物',`<div class="stack">${pets.map(p=>`<button class="glass card row pet-list-card" data-go="pet" data-id="${e(ctx,p.id)}">${photo(ctx,p,75)}<span class="grow"><strong>${e(ctx,p.name)}</strong><small class="muted">${e(ctx,p.breed)} · ${e(ctx,p.weight||'—')} kg</small><span>${tag(ctx,p.deceased?'永远被记得':p.sex||'小可爱')}${p.allergies?tag(ctx,'有护理注意事项'):''}</span></span>${icon(ctx,'arrow',20)}</button>`).join('')||noData(ctx,'记录它的小小日常','添加档案，照片、护理习惯和每一次认真照顾都会被记住。')}${act(ctx,`${icon(ctx,'plus',20)} 添加宠物档案`,'new-pet','','button secondary full')}</div>${section(ctx,'记录，值得被珍藏')}<div class="glass card row">${icon(ctx,'book',32)}<div class="grow"><strong>每一份护理手记</strong><p class="muted small">毛发、耳朵、指甲，还有它今天的乖。</p></div>${go(ctx,icon(ctx,'arrow',20),'reports','','button ghost')}</div>`,'home');}
function pet(ctx){const p=find(ownPets(ctx),ctx.id);if(!p)return missing(ctx,'宠物档案','pets');const reports=ownReports(ctx).filter(x=>x.petId===p.id).sort((a,b)=>b.date.localeCompare(a.date)), appts=ownAppointments(ctx).filter(x=>x.petId===p.id),latest=reports[0];return page(ctx,`${p.name}的小档案`,`<div class="glass pet-profile"><div class="pet-profile-picture">${photo(ctx,p,120)}</div><h2>${e(ctx,p.name)}</h2><p class="muted">${e(ctx,p.breed)} · ${e(ctx,p.sex||'性别未填写')}</p><div class="grid3 pet-stats"><div><strong>${e(ctx,p.weight||'—')}</strong><small>体重 kg</small></div><div><strong>${appts.filter(x=>x.status==='completed').length}</strong><small>到店照顾</small></div><div><strong>${reports.length}</strong><small>护理手记</small></div></div>${go(ctx,'编辑档案','pet-edit',p.id,'button secondary')}</div><section class="glass card stack">${datum(ctx,'生日',p.birthday)}${datum(ctx,'绝育信息',p.neutered===true||p.neutered==='true'?'已绝育':p.neutered===false||p.neutered==='false'?'未绝育':'未填写')}${datum(ctx,'所属主人',find(ctx.state.customers,'c1')?.name||'林女士')}${datum(ctx,'护理习惯',p.careNotes)}${datum(ctx,'过敏与注意事项',p.allergies||'暂无特别注意事项')}</section>${latest?`<div class="notice">${icon(ctx,'calendar',21)} 下次护理建议：${e(ctx,latest.nextAdvice||'3–4 周后，期待再次见面。')}</div>`:''}${section(ctx,'它的护理日记')}${reports.map(r=>reportCard(ctx,r)).join('')||noData(ctx,'小日记，等着被写下','完成第一次服务后，就会拥有专属护理手记。')}${section(ctx,'服务与预约记录')}<div class="stack">${appts.slice().reverse().slice(0,5).map(a=>appointmentCard(ctx,a)).join('')||'<p class="muted small">还没有服务记录。</p>'}</div>${!p.deceased?act(ctx,'为它预约下一次照顾','start-booking',`data-pet="${e(ctx,p.id)}"`,'button primary full'):''}`,'pets');}

function petEdit(ctx){const p=find(ownPets(ctx),ctx.id)||{},photoValue=ctx.draft.petPhotoId===(p.id||'new')?ctx.draft.petPhoto:p.photo;return page(ctx,p.id?'编辑宠物档案':'认识一下小可爱',`<form data-action="c.pet-save" class="stack" id="pet-edit-form" data-id="${e(ctx,p.id||'')}">${errorBox()}<div class="glass pet-upload"><div id="pet-photo-preview">${photo(ctx,{...p,photo:photoValue},100)}</div><label class="button secondary photo-upload-label">${icon(ctx,'image',19)} ${photoValue?'更换宠物照片':'上传宠物照片'}<input name="photoFile" id="pet-photo-input" type="file" accept="image/*"></label><p class="muted small">使用它自己的照片 · 支持相册或拍照<br>照片仅保存在当前演示数据中</p><input type="hidden" name="photo" value="${e(ctx,photoValue||'')}"></div><div class="glass card stack">${field(ctx,'宠物名字','name',p.name,'text','required maxlength="20" placeholder="例如：糯米"')}${field(ctx,'品种','breed',p.breed,'text','required maxlength="40" placeholder="例如：比熊"')}<label class="field"><span>宠物类型</span><select name="species" class="input"><option value="dog" ${p.species==='cat'?'':'selected'}>狗狗</option><option value="cat" ${p.species==='cat'?'selected':''}>猫咪</option></select></label><div class="grid2"><label class="field"><span>性别</span><select class="input" name="sex"><option value="男生" ${/男|雄/.test(p.sex||'')?'selected':''}>男生</option><option value="女生" ${/女|雌/.test(p.sex||'')?'selected':''}>女生</option><option value="未知" ${p.sex==='未知'?'selected':''}>暂不确定</option></select></label>${field(ctx,'体重 kg','weight',p.weight,'number','required min="0.1" max="120" step="0.1" inputmode="decimal"')}</div>${field(ctx,'生日（选填）','birthday',p.birthday,'date',`max="${ctx.state.today}"`)}<label class="field"><span>绝育信息</span><select name="neutered" class="input"><option value="" ${p.neutered==null?'selected':''}>暂不填写</option><option value="true" ${p.neutered===true||p.neutered==='true'?'selected':''}>已绝育</option><option value="false" ${p.neutered===false||p.neutered==='false'?'selected':''}>未绝育</option></select></label></div>${textarea(ctx,'护理习惯（选填）','careNotes',p.careNotes,'maxlength="500" placeholder="它喜欢怎样被照顾？"')}${textarea(ctx,'过敏与注意事项（选填）','allergies',p.allergies,'maxlength="500" placeholder="皮肤敏感、怕吹风或其他需要我们留意的事。"')}<button type="submit" class="button primary full">保存小档案 ${icon(ctx,'check',19)}</button></form>`,'pets');}

function reports(ctx){const pets=ownPets(ctx),selected=ctx.draft.reportPet||'all',list=ownReports(ctx).filter(x=>selected==='all'||x.petId===selected).sort((a,b)=>b.date.localeCompare(a.date));return page(ctx,'护理手记',`<div class="tabs scroll-chips">${act(ctx,'全部小可爱','report-filter','data-value="all"',`chip ${selected==='all'?'selected':''}`)}${pets.map(p=>act(ctx,e(ctx,p.name),'report-filter',`data-value="${e(ctx,p.id)}"`,`chip ${selected===p.id?'selected':''}`)).join('')}</div><p class="muted">今天的乖，我们都记住了。</p><div class="stack">${list.map(r=>reportCard(ctx,r)).join('')||noData(ctx,'每一次照顾，都值得收藏','服务完成后，护理师会把记录和温馨建议送到这里。',act(ctx,'约一次护理','start-booking'))}</div>`,'home');}
function itemLabel(value){return value===true?'已完成':value===false?'本次未进行':value||'已完成';}
function report(ctx){const r=find(ownReports(ctx),ctx.id);if(!r)return missing(ctx,'护理手记','reports');const p=petOf(ctx,r.petId),a=find(ctx.state.appointments,r.appointmentId),s=serviceOf(ctx,a),emp=find(ctx.state.employees,r.employeeId),gift=ownGifts(ctx).find(x=>x.reportId===r.id);return `<div class="customer-report"><section class="report-hero"><div class="scene report-scene" aria-hidden="true"></div><div class="report-hero-content">${go(ctx,`${icon(ctx,'chevron',20)} 护理手记`,'reports','','button ghost report-back')}<span class="glass season-label">${seasonNames[ctx.theme?.season]||'春'} · ${periodNames[ctx.theme?.period]||'清晨'}</span><h1>今天的乖，<br>我们都记住了。</h1><p>${e(ctx,p.name)}的第 ${ownReports(ctx).filter(x=>x.petId===p.id).length} 次护理手记</p></div></section><div class="page report-body"><article class="glass card report-complete"><div class="row">${photo(ctx,p,60)}<div class="grow"><h2>护理已完成</h2><p class="muted small">${e(ctx,s.name)} · 本次护理已完成</p></div><small>${e(ctx,r.date)}</small></div><div class="report-care-items grid3">${[['bath','毛发护理','fur'],['ear','耳部清洁','ears'],['scissors','指甲护理','nails']].map(([i,n,k])=>`<div>${icon(ctx,i,40)}<strong>${n}</strong><small>${e(ctx,itemLabel(r.items?.[k]))}</small></div>`).join('')}</div><div class="report-note"><div class="row"><span class="staff-avatar">${icon(ctx,'user',28)}</span><strong>护理师 ${e(ctx,emp?.name||'小夏')}</strong></div><p>${e(ctx,r.note||'今天很乖，谢谢你把这份小小的信任交给我们。')}</p>${r.behavior?`<small>本次表现：${e(ctx,r.behavior)}</small>`:''}</div><div class="between report-advice"><span class="row">${icon(ctx,'calendar',20)} 下次护理建议</span><strong>${e(ctx,r.nextAdvice||'3–4 周后')}</strong></div></article>${r.beforePhoto||r.afterPhoto?`<section class="glass card"><h2>记录它的小变化</h2><div class="grid2 report-photos">${r.beforePhoto?`<figure><img src="${e(ctx,ctx.ui.asset(r.beforePhoto))}" alt="护理前照片"><figcaption>护理前</figcaption></figure>`:''}${r.afterPhoto?`<figure><img src="${e(ctx,ctx.ui.asset(r.afterPhoto))}" alt="护理后照片"><figcaption>护理后</figcaption></figure>`:''}</div></section>`:''}${gift?`<button class="glass card row gift-preview" data-go="gift" data-id="${e(ctx,gift.id)}">${photo(ctx,{...p,photo:gift.photo||p.photo},78)}<span class="grow"><strong>送你一份小心意</strong><small class="muted">专属头像已做好 · 查看并保存</small></span>${icon(ctx,'arrow',21)}</button>`:''}<div class="grid2">${act(ctx,`${icon(ctx,'download',21)} 保存手记`,'save-report',`data-id="${e(ctx,r.id)}"`,'button secondary')}${act(ctx,'预约下次护理','start-booking',`data-pet="${e(ctx,p.id)}" data-service="${e(ctx,s.id||'')}"`)}</div><p class="small muted report-privacy">这份手记仅对你和授权护理团队可见。</p></div></div>`;}
function gift(ctx){const g=find(ownGifts(ctx),ctx.id);if(!g)return page(ctx,'一份小小心意',noData(ctx,'小礼物正在路上','护理师确认好头像后，你就能在护理手记中查看和保存。',go(ctx,'查看护理手记','reports')),'reports');const p=petOf(ctx,g.petId);return page(ctx,'送给你的小可爱',`<p class="gift-intro">谢谢你，把${e(ctx,p.name)}交给我们照顾。<br>把这份可爱，也一起收藏吧。</p><div class="glass gift-artwork"><div class="gift-sparkle">${icon(ctx,'gift',25)}</div><img class="gift-portrait" src="${e(ctx,ctx.ui.asset(g.photo||p.photo||'/assets/pet-dog.jpg'))}" alt="${e(ctx,p.name)}的专属头像"><h2>${e(ctx,p.name)}</h2><p>${e(ctx,g.theme||'四季小礼物')} · 被认真爱着的小可爱</p></div><div class="notice small">预设主题演示：保留这只宠物原始照片的毛色、花纹与脸型，主题装饰由页面呈现。未接入真实 AI 生图。</div><div class="stack">${act(ctx,`${icon(ctx,'download',21)} 保存头像原图`,'save-gift',`data-id="${e(ctx,g.id)}"`,'button primary full')}${act(ctx,'保存主题纪念卡','save-gift-card',`data-id="${e(ctx,g.id)}"`,'button secondary full')}${act(ctx,'复制分享文案','share-gift',`data-id="${e(ctx,g.id)}"`,'button ghost full')}${go(ctx,'想换一种风格，联系门店','contact','','button ghost full')}</div>`,'reports');}

function contact(ctx){const s=ctx.state.store;return page(ctx,'来店里，坐一坐',`<div class="glass store-hero"><span>${icon(ctx,'store',98)}</span><h2>${e(ctx,s.name)}</h2><p>${e(ctx,s.subtitle||'认真照顾每一份小小的信任')}</p>${tag(ctx,'演示门店')}</div><div class="glass card stack">${datum(ctx,'营业时间',s.hours||'09:00–18:00')}${datum(ctx,'联系电话',s.phone)}${datum(ctx,'门店地址',s.address)}</div><div class="grid2">${act(ctx,`${icon(ctx,'phone',20)} 查看电话`,'show-phone','','button primary')}${act(ctx,`${icon(ctx,'location',20)} 复制地址`,'copy-address','','button secondary')}</div><div class="glass card stack"><h2>到店前的小准备</h2><p class="muted">带上牵引绳或航空箱；如果有特殊的护理用品、皮肤情况或过敏史，请提前告诉护理师。</p>${act(ctx,'预约一次护理','start-booking','','button primary full')}</div><p class="small muted">本页为模拟门店资料。电话按钮仅展示与复制信息，不会拨打或向外部联系人发送消息。</p>`,'home');}
function profile(ctx){const c=find(ctx.state.customers,'c1')||{name:'林女士'},pets=ownPets(ctx),reports=ownReports(ctx);return page(ctx,'我的陪伴日常',`<div class="glass card profile-summary"><span class="profile-avatar">${icon(ctx,'user',38)}</span><div class="grow"><h2>${e(ctx,c.name)}</h2><p class="muted small">${e(ctx,String(c.phone||'138****6808').replace(/(\d{3})\d{4}(\d{4})/,'$1****$2'))}</p></div>${tag(ctx,'演示顾客')}</div><div class="grid3 profile-metrics"><div><strong>${pets.length}</strong><span>小可爱</span></div><div><strong>${ownAppointments(ctx).filter(x=>x.status==='completed').length}</strong><span>温暖照顾</span></div><div><strong>${reports.length}</strong><span>护理手记</span></div></div><div class="glass card profile-links">${[['calendar','我的预约','appointments'],['paw','我的宠物','pets'],['book','护理手记','reports'],['bell','消息与订阅','messages'],['store','联系门店','contact']].map(([i,t,r])=>`<button class="between" data-go="${r}"><span class="row">${icon(ctx,i,23)}${t}</span>${icon(ctx,'arrow',18)}</button>`).join('')}</div><div class="glass card"><h2>称呼与护理偏好</h2><form data-action="c.profile-save" class="stack">${errorBox()}${field(ctx,'怎么称呼你','name',c.name,'text','required maxlength="30"')}${textarea(ctx,'给门店的备注','notes',c.notes,'maxlength="500"')}<button class="button secondary full" type="submit">保存个人资料</button></form></div><p class="small muted">本演示使用模拟顾客身份；只展示该顾客自己的宠物、预约、报告与消息。</p>`,'home');}
function messages(ctx){const c=find(ctx.state.customers,'c1')||{},logs=(ctx.state.reminderLogs||[]).filter(x=>x.customerId==='c1').sort((a,b)=>String(b.date).localeCompare(String(a.date)));return page(ctx,'消息与订阅',`<div class="glass card"><h2>按你的心意，保持联系</h2><p class="muted small">这些开关记录演示授权状态，可以随时撤回。</p><form data-action="c.consent-save" class="stack">${errorBox()}<label class="preference-row"><span><strong>服务提醒</strong><small>护理预约、服务完成与护理建议</small></span><input type="checkbox" name="consent" ${c.consent?'checked':''}></label><label class="preference-row"><span><strong>活动与关怀</strong><small>生日祝福、复购关怀与门店活动</small></span><input type="checkbox" name="marketing" ${c.marketing?'checked':''}></label><div class="notice small">开启仅代表本 Demo 授权。真实微信订阅仍需调用官方授权能力；不会自动发送个人微信消息或真实短信。</div><button type="submit" class="button primary full">保存提醒偏好</button></form></div>${section(ctx,'门店消息',tag(ctx,'模拟记录'))}<div class="stack">${logs.map(l=>`<article class="glass card message-card"><div class="between"><strong>${l.channel==='manual'?'门店人工联系':l.channel==='sms'?'短信提醒（模拟）':'订阅提醒（模拟）'}</strong>${tag(ctx,['sent','success','simulated'].includes(l.status)?'模拟送达':l.status==='blocked'?'未发送':l.status)}</div><p>${e(ctx,l.text||l.reason||'门店给你留了一条护理提醒。')}</p>${l.reason?`<small class="muted">${e(ctx,l.reason)}</small>`:''}<small class="muted">${e(ctx,l.date)}</small></article>`).join('')||noData(ctx,'暂时没有新消息','门店的护理关怀会安静地留在这里。')}</div>`,'profile');}
function missing(ctx,name,back){return page(ctx,`${name}暂不可见`,noData(ctx,'这份记录暂时找不到','可能已更新，或不属于当前顾客与门店。',go(ctx,'返回列表',back)),back);}

export function renderCustomer(ctx){
 const renderers={home,services,service,'select-pet':selectPet,booking,confirm,success,appointments,appointment,pets,pet,'pet-edit':petEdit,reports,report,gift,contact,profile,messages};
 return (renderers[ctx.page]||home)(ctx);
}

function formValues(form){return Object.fromEntries(new FormData(form).entries());}
function showError(form,message){const box=form.querySelector('.form-error');if(box){box.textContent=message;box.hidden=false;box.scrollIntoView({block:'center',behavior:'smooth'});}}
function resultId(r){return r?.result?.id||r?.id||r?.result?.appointment?.id;}
function readBookingForm(form,ctx){const v=formValues(form);ctx.draft.booking={...draftBooking(ctx),petId:v.petId,serviceId:v.serviceId||draftBooking(ctx).serviceId,date:v.date,employeeId:v.employeeId||'',time:v.time||'',notes:v.notes||''};return ctx.draft.booking;}
async function saveAsset(src,name){const response=await fetch(src);if(!response.ok)throw new Error('图片暂时无法读取，请稍后重试。');const blob=await response.blob(),url=URL.createObjectURL(blob);window.dispatchEvent(new CustomEvent('image-export',{detail:{url,name}}));}
function reportText(ctx,r){const a=find(ctx.state.appointments,r.appointmentId),staff=find(ctx.state.employees,r.employeeId);return [`${r.date} · ${serviceOf(ctx,a).name} · 护理师 ${staff?.name||'小夏'}`,`毛发：${itemLabel(r.items?.fur)}  耳朵：${itemLabel(r.items?.ears)}  指甲：${itemLabel(r.items?.nails)}`,`本次表现：${r.behavior||'乖巧配合'}`,r.note||'',`下次护理：${r.nextAdvice||'3–4 周后'}`].join('\n');}

export async function handleCustomer(action,el,ctx){
 if(!action?.startsWith('c.'))return false;
 const name=action.slice(2),id=el.dataset.id;
 try{
  switch(name){
   case 'home-menu':ctx.modal(`<div class="stack"><p class="eyebrow">云朵宠物 · H5 演示</p><h2>把陪伴，放在心上</h2>${act(ctx,'我的陪伴日常','menu-go','data-page="profile"','button secondary full')}${act(ctx,'消息与订阅','menu-go','data-page="messages"','button secondary full')}${act(ctx,'联系门店','menu-go','data-page="contact"','button secondary full')}${act(ctx,'继续逛逛','close-modal','','button ghost full')}</div>`);break;
   case 'menu-go':ctx.closeModal();ctx.go(el.dataset.page);break;
   case 'service-category':ctx.draft.serviceCategory=el.dataset.value;ctx.refresh();break;
   case 'appointment-filter':ctx.draft.appointmentFilter=el.dataset.value;ctx.refresh();break;
   case 'report-filter':ctx.draft.reportPet=el.dataset.value;ctx.refresh();break;
   case 'start-booking':{const d=draftBooking(ctx);ctx.draft.booking={...d,editId:undefined,time:'',date:ctx.state.today,employeeId:'',serviceId:el.dataset.service||d.serviceId,petId:el.dataset.pet||d.petId};if(el.dataset.pet)ensurePetService(ctx,ctx.draft.booking);ctx.go(el.dataset.pet?'booking':'select-pet');break;}
   case 'choose-pet':draftBooking(ctx).petId=id;ensurePetService(ctx,draftBooking(ctx));ctx.go('booking');break;
   case 'new-pet':ctx.draft.petReturn=el.dataset.return||'';ctx.draft.petPhoto='';ctx.draft.petPhotoId='new';ctx.go('pet-edit');break;
   case 'slot':{const form=document.querySelector('#customer-booking-form'),d=form?readBookingForm(form,ctx):draftBooking(ctx);d.time=el.dataset.time;if(form){form.elements.time.value=d.time;const err=form.querySelector('.form-error');if(err){err.hidden=true;err.textContent='';}form.querySelectorAll('.slot').forEach(b=>{const yes=b.dataset.time===d.time;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes));if(!b.disabled)b.querySelector('small').textContent=yes?'已选择':'可预约';});}break;}
   case 'booking-review':{if(!el.reportValidity())break;const d=readBookingForm(el,ctx);if(!d.time){showError(el,'请选择一个可以预约的开始时间。');break;}const staff=slotEmployee(ctx,d,d.time);if(!staff){showError(el,'这个时段无法完成所选服务，请重新选择时间或护理师。');break;}ctx.draft.booking={...d,employeeId:staff.id};ctx.go('confirm');break;}
   case 'booking-submit':{if(!el.reportValidity())break;const d=draftBooking(ctx);let r;if(d.editId)r=await ctx.mutate('booking.update',{id:d.editId,date:d.date,time:d.time,employeeId:d.employeeId});else r=await ctx.mutate('booking.create',{petId:d.petId,serviceId:d.serviceId,employeeId:d.employeeId,date:d.date,time:d.time,notes:d.notes,opportunityId:d.opportunityId});const rid=d.editId||resultId(r);ctx.draft.lastBookingId=rid;delete ctx.draft.booking;ctx.go('success',rid);break;}
   case 'edit-booking':{const a=find(ownAppointments(ctx),id);if(!a||!editableStatuses.includes(a.status))throw new Error('当前预约状态不能修改，请联系门店。');ctx.draft.booking={...a,editId:a.id};ctx.go('booking');break;}
   case 'cancel-booking':{const a=find(ownAppointments(ctx),id);if(!a||!editableStatuses.includes(a.status))throw new Error('当前预约状态不能取消，请联系门店。');ctx.modal(`<form data-action="c.cancel-confirm" data-id="${e(ctx,id)}" class="stack"><h2>取消这次预约？</h2><p class="muted">${e(ctx,a.date)} ${e(ctx,a.time)} · ${e(ctx,petOf(ctx,a.petId).name)}</p>${errorBox()}${textarea(ctx,'告诉我们原因（选填）','reason','','maxlength="200" placeholder="例如：临时有事，想改天再来。"')}<button class="button danger full" type="submit">确认取消预约</button>${act(ctx,'保留预约','close-modal','','button secondary full')}</form>`);break;}
   case 'cancel-confirm':await ctx.mutate('booking.cancel',{id,reason:formValues(el).reason||'顾客取消'});ctx.closeModal();ctx.go('appointment',id);ctx.toast('预约已取消，期待下次见面。');break;
   case 'close-modal':ctx.closeModal();break;
   case 'pet-save':{if(!el.reportValidity())break;const v=formValues(el),payload={id:id||undefined,customerId:'c1',name:v.name.trim(),breed:v.breed.trim(),species:v.species,sex:v.sex,birthday:v.birthday,weight:Number(v.weight),neutered:v.neutered===''?null:v.neutered==='true',careNotes:v.careNotes,allergies:v.allergies,photo:v.photo};if(!payload.name||!payload.breed)throw new Error('请填写宠物名字和品种。');if(v.photo&&!/^(data:image\/(jpeg|png|webp);base64,|\.?\/assets\/)/.test(v.photo))throw new Error('请选择有效的宠物图片。');const r=await ctx.mutate('pet.save',payload);const pid=id||resultId(r);ctx.draft.petPhotoId='';if(ctx.draft.petReturn==='booking'){draftBooking(ctx).petId=pid;ensurePetService(ctx,draftBooking(ctx),payload);ctx.draft.petReturn='';ctx.go('booking');}else ctx.go('pet',pid);ctx.toast('小档案已保存');break;}
   case 'save-report':{const r=find(ownReports(ctx),id);if(!r)throw new Error('未找到这份护理手记');await ctx.ui.downloadPoster({kind:'report',title:`${petOf(ctx,r.petId).name}的护理手记`,subtitle:'今天的乖，我们都记住了。',pet:petOf(ctx,r.petId),footer:reportText(ctx,r),theme:ctx.theme});ctx.toast('护理手记已生成，可保存到相册');break;}
   case 'save-gift':{const g=find(ownGifts(ctx),id);if(!g)throw new Error('礼物尚未确认');const p=petOf(ctx,g.petId);await saveAsset(ctx.ui.asset(g.photo||p.photo||'/assets/pet-dog.jpg'),`${p.name}-专属头像.jpg`);ctx.toast('头像原图已打开，可以长按保存到相册');break;}
   case 'save-gift-card':{const g=find(ownGifts(ctx),id),p=petOf(ctx,g?.petId);if(!g)throw new Error('礼物尚未确认');await ctx.ui.downloadPoster({kind:'gift',themeName:g.theme||'四季小礼物',title:p.name,subtitle:'被认真爱着的小可爱',pet:{...p,photo:g.photo||p.photo},footer:`${ctx.state.store.name}\n${g.theme||'四季小礼物'} · 预设主题演示`,theme:ctx.theme});ctx.toast('主题纪念卡已生成');break;}
   case 'share-gift':{const g=find(ownGifts(ctx),id),p=petOf(ctx,g?.petId);await ctx.ui.copy(`今天的${p.name}，被认真照顾，也被温柔记住。谢谢${ctx.state.store.name}送来的小小心意。`);ctx.toast('分享文案已复制，可自行选择分享对象');break;}
   case 'copy-address':await ctx.ui.copy(ctx.state.store.address||'模拟门店地址');ctx.toast('门店地址已复制');break;
   case 'show-phone':ctx.modal(`<div class="stack"><span class="eyebrow">模拟门店联系方式</span><h2>${e(ctx,ctx.state.store.phone)}</h2><p class="muted">此号码为演示资料。你可以复制号码查看，不会发起电话。</p>${act(ctx,'复制号码','copy-phone','','button primary full')}${act(ctx,'关闭','close-modal','','button secondary full')}</div>`);break;
   case 'copy-phone':await ctx.ui.copy(ctx.state.store.phone||'');ctx.toast('演示号码已复制');break;
   case 'profile-save':{if(!el.reportValidity())break;const v=formValues(el);await ctx.mutate('profile.save',{name:v.name.trim(),notes:v.notes});ctx.toast('个人资料已保存');ctx.refresh();break;}
   case 'consent-save':{const v=formValues(el);await ctx.mutate('consent.update',{consent:v.consent==='on',marketing:v.marketing==='on'});ctx.toast('提醒偏好已更新，门店会尊重你的选择');ctx.refresh();break;}
   default:return false;
  }
 }catch(err){if(el.tagName==='FORM')showError(el,err.message||'提交未完成，请稍后重试。');else ctx.toast(err.message||'操作未完成，请稍后重试。');}
 return true;
}

const reportsBeingViewed=new Set();
export function mountCustomer(ctx){
 const form=document.querySelector('#customer-booking-form');
 if(form){for(const name of ['serviceId','date','employeeId'])form.querySelector(`select[name="${name}"],input[name="${name}"]`)?.addEventListener('change',()=>{const d=readBookingForm(form,ctx);d.time='';if(name==='serviceId')d.employeeId='';ctx.refresh();});}
 const upload=document.querySelector('#pet-photo-input');
 if(upload)upload.addEventListener('change',async()=>{
  const file=upload.files?.[0];if(!file)return;
  try{
   if(!/^image\/(jpeg|png|webp|gif|heic|heif)$/.test(file.type)&&!(/\.(jpe?g|png|webp|heic|heif)$/i.test(file.name)))throw new Error('请选择 JPG、PNG 或手机相册中的照片。');
   if(file.size>15*1024*1024)throw new Error('这张照片超过 15 MB，请选择较小的照片。');
   const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('照片读取失败'));r.readAsDataURL(file);});
   const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('当前浏览器无法解码这张照片，请转为 JPG 后重试。'));i.src=data;});
   const ratio=Math.min(1,1000/img.width,1000/img.height),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);const cx=canvas.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,canvas.width,canvas.height);cx.drawImage(img,0,0,canvas.width,canvas.height);const result=canvas.toDataURL('image/jpeg',0.83),petForm=document.querySelector('#pet-edit-form');
   ctx.draft.petPhoto=result;ctx.draft.petPhotoId=ctx.id||'new';petForm.elements.photo.value=result;document.querySelector('#pet-photo-preview').innerHTML=`<img class="avatar" style="width:100px;height:100px;object-fit:cover;border-radius:50%" src="${result}" alt="新宠物照片预览">`;ctx.toast('照片已准备好，保存档案后生效');
  }catch(err){ctx.toast(err.message);upload.value='';}
 });
 if(ctx.page==='report'){const r=find(ownReports(ctx),ctx.id);const key=`${ctx.storeId}:${r?.id}`;if(r&&!r.viewed&&!reportsBeingViewed.has(key)){reportsBeingViewed.add(key);Promise.resolve(ctx.mutate('report.view',{id:r.id})).catch(()=>{}).finally(()=>reportsBeingViewed.delete(key));}}
}






